    def receiveInteraction(
        self,
        interactionClass: InteractionClassHandle,
        parameterValues: ParameterHandleValueMap,
        userSuppliedTag: bytes,
        transportationType: TransportationTypeHandle,
        producingFederate: FederateHandle,
        optionalSentRegions: object | None = None,
        time: HLAinteger64Time | None = None,
        sentOrderType: OrderType | None = None,
        receivedOrderType: OrderType | None = None,
        retraction: MessageRetractionHandle | None = None,
    ) -> None:
        values = (
            interactionClass,
            parameterValues,
            bytes(userSuppliedTag),
            transportationType,
            producingFederate,
        )
        if time is None and optionalSentRegions is None:
            self.received_interactions.append(values)
        elif time is None:
            self.regional_interactions.append(values + (optionalSentRegions,))
        else:
            self.timestamped_interactions.append(
                values
                + (
                    optionalSentRegions,
                    time,
                    sentOrderType,
                    receivedOrderType,
                    retraction,
                )
            )

