    def test_jni_bridge_artifact_does_not_shadow_external_api(self) -> None:
        """Keep the standard API in the supplied JAR, not in the JNI bridge."""
        with zipfile.ZipFile(self.artifacts.bridge_jar) as bridge:
            entries = set(bridge.namelist())
        self.assertFalse(
            any(entry.startswith("hla/rti1516_2025/") for entry in entries),
            "the JNI bridge must not bundle or shadow IEEE Java API classes",
        )
        self.assertEqual(
            {
                entry
                for entry in entries
                if entry.startswith("META-INF/services/") and not entry.endswith("/")
            },
            {
                "META-INF/services/hla.rti1516_2025.RtiFactory",
                "META-INF/services/hla.rti1516_2025.auth.AuthorizerFactory",
            },
        )
        with zipfile.ZipFile(self.artifacts.bridge_jar) as bridge:
            self.assertEqual(
                bridge.read("META-INF/services/hla.rti1516_2025.RtiFactory")
                .decode("utf-8")
                .splitlines(),
                ["org.umbra.jni.rti1516_2025.NativeRtiFactory"],
            )
            self.assertEqual(
                bridge.read("META-INF/services/hla.rti1516_2025.auth.AuthorizerFactory")
                .decode("utf-8")
                .splitlines(),
                ["org.umbra.jni.rti1516_2025.NativeAuthorizerFactory"],
            )

    def test_jni_java_facade_keeps_only_native_handle_state(self) -> None:
        """Prevent the Java façade from becoming a second RTI implementation."""
        handler = (
            Path(__file__).parents[2]
            / "umbra-rti-jni"
            / "src"
            / "main"
            / "java"
            / "org"
            / "umbra"
            / "jni"
            / "rti1516_2025"
            / "NativeRTIambassador.java"
        ).read_text(encoding="utf-8")

        # Java may marshal standard value objects and create temporary
        # collection proxies, but federation membership, callbacks, DDM,
        # ownership, and time state must remain in C++.  Keep this assertion
        # deliberately source-level: a Java field added later would otherwise
        # be invisible to the end-to-end service inventory until it diverged.
        instance_fields = re.findall(
            r"(?m)^\s+private\s+(?!static\b)([^;{}\n]+);\s*$", handler
        )
        self.assertEqual(
            instance_fields,
            ["long nativeHandle = NativeBridge.nativeCreate()"],
            "the JNI façade must not carry a parallel Java RTI state model",
        )
        self.assertNotRegex(
            handler,
            r"private\s+(?:final\s+)?(?:Map|HashMap|Set|HashSet|List|Queue|Deque)<",
            "stateful Java collections must not replace C++ RTI state",
        )

    def test_cpp_jni_java_jpype_standard_authorizer_service(self) -> None:
        """The Java authorization ServiceLoader delegates policy to C++."""
        import jpype

        self.factory.getRtiAmbassador()
        system = jpype.java.lang.System
        property_name = "umbra.rti.jni.authorizer.password"
        previous_password = system.getProperty(property_name)
        try:
            system.setProperty(property_name, "jni-authorizer-password")
            factory_factory = jpype.JClass(
                "hla.rti1516_2025.auth.AuthorizerFactoryFactory"
            )
            authorizer_factory = factory_factory.getAuthorizerFactory("HLAauthorizer")
            self.assertIsNotNone(authorizer_factory)
            self.assertEqual(authorizer_factory.getName(), "HLAauthorizer")
            authorizer = authorizer_factory.getAuthorizer()
            authorizer_type = jpype.JClass("hla.rti1516_2025.auth.Authorizer").class_
            self.assertTrue(authorizer_type.isAssignableFrom(authorizer.getClass()))

            credentials_type = jpype.JClass("hla.rti1516_2025.auth.Credentials")
            password_type = jpype.JClass(
                "hla.rti1516_2025.auth.HLAplainTextPassword"
            )
            no_credentials_type = jpype.JClass(
                "hla.rti1516_2025.auth.HLAnoCredentials"
            )

            def code(result: object) -> str:
                return str(result.code.name())

            matching = password_type("jni-authorizer-password")
            self.assertEqual(code(authorizer.authorizeRtiOperation(matching)), "AUTHORIZED")
            self.assertEqual(
                code(authorizer.authorizeFederationOperation(matching, "jni-federation")),
                "AUTHORIZED",
            )
            self.assertEqual(
                code(
                    authorizer.authorizeFederateOperation(
                        matching, "jni-federation", "jni-federate", "jni-type"
                    )
                ),
                "AUTHORIZED",
            )
            self.assertEqual(
                code(authorizer.authorizeRtiOperation(password_type("wrong-password"))),
                "UNAUTHORIZED",
            )
            self.assertEqual(
                code(authorizer.authorizeRtiOperation(no_credentials_type())),
                "UNAUTHORIZED",
            )
            malformed = jpype.JArray(jpype.JByte)([0, 0, 0, 1, 0])
            self.assertEqual(
                code(
                    authorizer.authorizeRtiOperation(
                        credentials_type("HLAplainTextPassword", malformed)
                    )
                ),
                "INVALID_CREDENTIALS",
            )
            self.assertEqual(
                code(
                    authorizer.authorizeRtiOperation(
                        credentials_type("vendor-credential", jpype.JArray(jpype.JByte)([]))
                    )
                ),
                "UNAUTHORIZED",
            )

            system.clearProperty(property_name)
            unconfigured = authorizer_factory.getAuthorizer()
            self.assertEqual(
                code(unconfigured.authorizeRtiOperation(no_credentials_type())),
                "AUTHORIZATION_ERROR",
            )
        finally:
            if previous_password is None:
                system.clearProperty(property_name)
            else:
                system.setProperty(property_name, previous_password)

    def test_cpp_jni_java_jpype_standard_encoder_handle_and_time_carriers(self) -> None:
        """Standard Java EncoderFactory carriers remain C++-validated."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-standard-encoders-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = False
        joined = False
        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            ambassador.joinFederationExecution(
                "jni-standard-encoder",
                federation_name,
                federateName="jni-standard-encoder",
            )
            joined = True

            # Deliberately use the raw Java objects.  This invokes the exact
            # IEEE EncoderFactory overloads through the JNI proxy, while all
            # handle values still originate in C++ standard factories.
            raw_ambassador = ambassador.unwrap_java_object()
            raw_encoder = self.factory.unwrap_java_encoder_factory()

            object_class = raw_ambassador.getObjectClassHandle(
                "HLAobjectRoot.Employee.Server"
            )
            attribute = raw_ambassador.getAttributeHandle(object_class, "Efficiency")
            interaction = raw_ambassador.getInteractionClassHandle(
                "HLAinteractionRoot.ServerAction.TakeOrder"
            )
            parameter_class = raw_ambassador.getInteractionClassHandle(
                "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
            )
            parameter = raw_ambassador.getParameterHandle(parameter_class, "TemperatureOk")
            dimension = raw_ambassador.getDimensionHandle("ServerId")
            transportation = raw_ambassador.getTransportationTypeHandle("HLAreliable")

            attribute_set = raw_ambassador.getAttributeHandleSetFactory().create()
            attribute_set.add(attribute)
            raw_ambassador.publishObjectClassAttributes(object_class, attribute_set)
            object_instance = raw_ambassador.registerObjectInstance(object_class)

            dimension_set = raw_ambassador.getDimensionHandleSetFactory().create()
            dimension_set.add(dimension)
            region = raw_ambassador.createRegion(dimension_set)
            federate = raw_ambassador.getFederateHandle("jni-standard-encoder")

            handle_cases = (
                ("createHLAfederateHandle", federate, FederateHandle),
                ("createHLAobjectClassHandle", object_class, ObjectClassHandle),
                ("createHLAinteractionClassHandle", interaction, InteractionClassHandle),
                ("createHLAobjectInstanceHandle", object_instance, ObjectInstanceHandle),
                ("createHLAattributeHandle", attribute, AttributeHandle),
                ("createHLAparameterHandle", parameter, ParameterHandle),
                ("createHLAdimensionHandle", dimension, DimensionHandle),
                ("createHLAregionHandle", region, RegionHandle),
                (
                    "createHLAtransportationTypeHandle",
                    transportation,
                    TransportationTypeHandle,
                ),
            )
            import jpype

            python_encoder = self.factory.getEncoderFactory()
            encoder_interface = jpype.JClass(
                "hla.rti1516_2025.encoding.EncoderFactory"
            ).class_
            java_creator_names = {
                str(method.getName()) for method in encoder_interface.getMethods()
            }
            python_creator_names = {
                name
                for name in dir(type(python_encoder))
                if name.startswith("createHLA")
            }
            self.assertTrue(python_creator_names <= java_creator_names)
            self.assertEqual(
                java_creator_names - python_creator_names,
                set(),
            )
            for method_name, handle, handle_type in handle_cases:
                with self.subTest(method_name=method_name):
                    element = getattr(raw_encoder, method_name)(raw_ambassador, handle)
                    self.assertTrue(handle.equals(element.getValue()))
                    encoded = bytes(element.toByteArray())
                    self.assertEqual(element.getEncodedLength(), len(encoded))
                    decoded = getattr(raw_encoder, method_name)(raw_ambassador)
                    decoded.decode(encoded)
                    self.assertTrue(handle.equals(decoded.getValue()))

                    # The provider-scoped Python façade calls the same exact
                    # Java creator and converts only the handle value.  It
                    # must not introduce a Python-side wire representation.
                    python_handle = handle_type(ambassador._runtime.handle_bytes(handle))
                    python_element = getattr(python_encoder, method_name)(
                        ambassador, python_handle
                    )
                    self.assertEqual(python_element.getValue(), python_handle)
                    python_encoded = python_element.toByteArray()
                    self.assertEqual(python_encoded, encoded)
                    python_decoded = getattr(python_encoder, method_name)(ambassador)
                    python_decoded.decode(python_encoded)
                    self.assertEqual(python_decoded.getValue(), python_handle)

            # Exercise the exact standard Java ByteWrapper cursor overloads,
            # including non-zero offsets and the consumed-byte contract.  The
            # Java carrier only moves the cursor; C++ still owns the encoded
            # representation and decoder validation.
            byte_wrapper_type = jpype.JClass(
                "hla.rti1516_2025.encoding.ByteWrapper"
            )
            integer_element = raw_encoder.createHLAinteger32BE(0x01020304)
            encode_buffer = jpype.JArray(jpype.JByte)([0] * 6)
            encode_wrapper = byte_wrapper_type(encode_buffer, 1, 4)
            integer_element.encode(encode_wrapper)
            self.assertEqual(encode_wrapper.getPos(), 5)
            self.assertEqual(
                bytes(encode_buffer), b"\0\x01\x02\x03\x04\0"
            )

            decode_buffer = jpype.JArray(jpype.JByte)(
                [0x55, 0x01, 0x02, 0x03, 0x04, 0x66]
            )
            decode_wrapper = byte_wrapper_type(decode_buffer, 1, 4)
            decoded_integer = raw_encoder.createHLAinteger32BE()
            decoded_integer.decode(decode_wrapper)
            self.assertEqual(decoded_integer.getValue(), 0x01020304)
            self.assertEqual(decode_wrapper.getPos(), 5)
            self.assertEqual(decode_wrapper.remaining(), 0)

            # The Python Java façade exposes the same exact cursor overloads
            # without converting the ByteWrapper into a Python buffer.
            python_integer = python_encoder.createHLAinteger32BE(0x01020304)
            python_encode_buffer = jpype.JArray(jpype.JByte)([0] * 6)
            python_encode_wrapper = byte_wrapper_type(python_encode_buffer, 1, 4)
            self.assertIs(python_integer.encode(python_encode_wrapper), python_integer)
            self.assertEqual(python_encode_wrapper.getPos(), 5)
            self.assertEqual(bytes(python_encode_buffer), b"\0\x01\x02\x03\x04\0")

            python_decode_wrapper = byte_wrapper_type(decode_buffer, 1, 4)
            python_decoded_integer = python_encoder.createHLAinteger32BE()
            self.assertIs(
                python_decoded_integer.decode(python_decode_wrapper),
                python_decoded_integer,
            )
            self.assertEqual(python_decoded_integer.getValue(), 0x01020304)
            self.assertEqual(python_decode_wrapper.getPos(), 5)
            self.assertEqual(python_decode_wrapper.remaining(), 0)

            short_wrapper = byte_wrapper_type(
                jpype.JArray(jpype.JByte)([0x01, 0x02, 0x03]), 0, 3
            )
            java_decoder_exception = jpype.JClass(
                "hla.rti1516_2025.encoding.DecoderException"
            )
            with self.assertRaises(java_decoder_exception):
                raw_encoder.createHLAinteger32BE().decode(short_wrapper)
            with self.assertRaises(DecoderException):
                python_encoder.createHLAinteger32BE().decode(
                    byte_wrapper_type(
                        jpype.JArray(jpype.JByte)([0x01, 0x02, 0x03]),
                        0,
                        3,
                    )
                )
            signed_decoder_cases = (
                ("HLAinteger16BE", raw_encoder.createHLAinteger16BE, b"\0"),
                ("HLAinteger16LE", raw_encoder.createHLAinteger16LE, b"\0"),
                ("HLAinteger32BE", raw_encoder.createHLAinteger32BE, b"\0" * 3),
                ("HLAinteger32LE", raw_encoder.createHLAinteger32LE, b"\0" * 3),
                ("HLAinteger64BE", raw_encoder.createHLAinteger64BE, b"\0" * 7),
                ("HLAinteger64LE", raw_encoder.createHLAinteger64LE, b"\0" * 7),
            )
            for name, create_signed, malformed in signed_decoder_cases:
                with self.subTest(decoder=name):
                    with self.assertRaises(java_decoder_exception):
                        create_signed().decode(malformed)

            # The same cursor contract must hold for a native composite, not
            # just a primitive.  Its child alignment and decoded length stay
            # C++-owned while the standard Java wrapper advances once for the
            # whole record.
            cursor_record = raw_encoder.createHLAfixedRecord()
            cursor_record.appendElement(raw_encoder.createHLAinteger32BE(7))
            cursor_record.appendElement(raw_encoder.createHLAoctet(9))
            cursor_record_encoded = bytes(cursor_record.toByteArray())
            cursor_record_buffer = jpype.JArray(jpype.JByte)(
                [0] + list(cursor_record_encoded) + [0]
            )
            cursor_record_wrapper = byte_wrapper_type(
                cursor_record_buffer, 1, len(cursor_record_encoded)
            )
            cursor_record.encode(cursor_record_wrapper)
            self.assertEqual(
                cursor_record_wrapper.getPos(), 1 + len(cursor_record_encoded)
            )
            self.assertEqual(
                bytes(cursor_record_buffer),
                b"\0" + cursor_record_encoded + b"\0",
            )
            decoded_cursor_record = raw_encoder.createHLAfixedRecord()
            decoded_cursor_record.appendElement(raw_encoder.createHLAinteger32BE())
            decoded_cursor_record.appendElement(raw_encoder.createHLAoctet())
            decode_cursor_record_wrapper = byte_wrapper_type(
                cursor_record_buffer, 1, len(cursor_record_encoded)
            )
            decoded_cursor_record.decode(decode_cursor_record_wrapper)
            self.assertEqual(decode_cursor_record_wrapper.remaining(), 0)
            self.assertEqual(decoded_cursor_record.get(0).getValue(), 7)
            self.assertEqual(decoded_cursor_record.get(1).getValue(), 9)

            python_cursor_record = python_encoder.createHLAfixedRecord()
            python_cursor_record.appendElement(python_encoder.createHLAinteger32BE(7))
            python_cursor_record.appendElement(python_encoder.createHLAoctet(9))
            python_record_buffer = jpype.JArray(jpype.JByte)(
                [0] + list(cursor_record_encoded) + [0]
            )
            python_record_wrapper = byte_wrapper_type(
                python_record_buffer, 1, len(cursor_record_encoded)
            )
            self.assertIs(
                python_cursor_record.encode(python_record_wrapper),
                python_cursor_record,
            )
            self.assertEqual(python_record_wrapper.getPos(), 1 + len(cursor_record_encoded))
            python_decoded_record = python_encoder.createHLAfixedRecord()
            python_decoded_record.appendElement(python_encoder.createHLAinteger32BE())
            python_decoded_record.appendElement(python_encoder.createHLAoctet())
            python_decode_record_wrapper = byte_wrapper_type(
                python_record_buffer, 1, len(cursor_record_encoded)
            )
            python_decoded_record.decode(python_decode_record_wrapper)
            self.assertEqual(python_decode_record_wrapper.remaining(), 0)
            self.assertEqual(python_decoded_record.get(0).getValue(), 7)
            self.assertEqual(python_decoded_record.get(1).getValue(), 9)

            # Variable-length standard carriers use the same cursor contract:
            # the length prefix and payload are still produced and validated
            # by C++, while the exact Java ByteWrapper owns only the offset and
            # consumed-position bookkeeping.
            cursor_ascii = raw_encoder.createHLAASCIIstring("Hi")
            cursor_ascii_encoded = bytes(cursor_ascii.toByteArray())
            cursor_ascii_buffer = jpype.JArray(jpype.JByte)(
                [0] + list(cursor_ascii_encoded) + [0]
            )
            cursor_ascii_wrapper = byte_wrapper_type(
                cursor_ascii_buffer, 1, len(cursor_ascii_encoded)
            )
            cursor_ascii.encode(cursor_ascii_wrapper)
            self.assertEqual(
                cursor_ascii_wrapper.getPos(), 1 + len(cursor_ascii_encoded)
            )
            decoded_cursor_ascii = raw_encoder.createHLAASCIIstring()
            decode_cursor_ascii_wrapper = byte_wrapper_type(
                cursor_ascii_buffer, 1, len(cursor_ascii_encoded)
            )
            decoded_cursor_ascii.decode(decode_cursor_ascii_wrapper)
            self.assertEqual(decoded_cursor_ascii.getValue(), "Hi")
            self.assertEqual(decode_cursor_ascii_wrapper.remaining(), 0)
            with self.assertRaises(java_decoder_exception):
                raw_encoder.createHLAASCIIstring().decode(
                    byte_wrapper_type(
                        jpype.JArray(jpype.JByte)([0, 0, 0, 2, 0x48]),
                        0,
                        5,
                    )
                )

            cursor_unicode = raw_encoder.createHLAunicodeString("A\u03a9")
            cursor_unicode_encoded = bytes(cursor_unicode.toByteArray())
            cursor_unicode_buffer = jpype.JArray(jpype.JByte)(
                [0]
                + [
                    value if value < 128 else value - 256
                    for value in cursor_unicode_encoded
                ]
                + [0]
            )
            cursor_unicode_wrapper = byte_wrapper_type(
                cursor_unicode_buffer, 1, len(cursor_unicode_encoded)
            )
            cursor_unicode.encode(cursor_unicode_wrapper)
            self.assertEqual(
                cursor_unicode_wrapper.getPos(), 1 + len(cursor_unicode_encoded)
            )
            decoded_cursor_unicode = raw_encoder.createHLAunicodeString()
            decode_cursor_unicode_wrapper = byte_wrapper_type(
                cursor_unicode_buffer, 1, len(cursor_unicode_encoded)
            )
            decoded_cursor_unicode.decode(decode_cursor_unicode_wrapper)
            self.assertEqual(decoded_cursor_unicode.getValue(), "A\u03a9")
            self.assertEqual(decode_cursor_unicode_wrapper.remaining(), 0)

            cursor_opaque = raw_encoder.createHLAopaqueData(
                jpype.JArray(jpype.JByte)([1, 2, 3])
            )
            cursor_opaque_encoded = bytes(cursor_opaque.toByteArray())
            cursor_opaque_buffer = jpype.JArray(jpype.JByte)(
                [0] + list(cursor_opaque_encoded) + [0]
            )
            cursor_opaque_wrapper = byte_wrapper_type(
                cursor_opaque_buffer, 1, len(cursor_opaque_encoded)
            )
            cursor_opaque.encode(cursor_opaque_wrapper)
            self.assertEqual(
                cursor_opaque_wrapper.getPos(), 1 + len(cursor_opaque_encoded)
            )
            decoded_cursor_opaque = raw_encoder.createHLAopaqueData()
            decode_cursor_opaque_wrapper = byte_wrapper_type(
                cursor_opaque_buffer, 1, len(cursor_opaque_encoded)
            )
            decoded_cursor_opaque.decode(decode_cursor_opaque_wrapper)
            self.assertEqual(bytes(decoded_cursor_opaque.getValue()), b"\x01\x02\x03")
            self.assertEqual(decode_cursor_opaque_wrapper.remaining(), 0)

            # A variable array exercises the standard Java
            # DataElementFactory/JArray overload while retaining C++ count,
            # child alignment, and cursor-consumption semantics.
            data_element_type = jpype.JClass(
                "hla.rti1516_2025.encoding.DataElement"
            )
            variable_factory = jpype.JProxy(
                "hla.rti1516_2025.encoding.DataElementFactory",
                dict(createElement=lambda index: raw_encoder.createHLAinteger32BE()),
            )
            variable_values = jpype.JArray(data_element_type)(
                [
                    raw_encoder.createHLAinteger32BE(11),
                    raw_encoder.createHLAinteger32BE(-12),
                ]
            )
            cursor_variable = raw_encoder.createHLAvariableArray(
                variable_factory, variable_values
            )
            cursor_variable_encoded = bytes(cursor_variable.toByteArray())
            cursor_variable_buffer = jpype.JArray(jpype.JByte)(
                [0]
                + [
                    value if value < 128 else value - 256
                    for value in cursor_variable_encoded
                ]
                + [0]
            )
            cursor_variable_wrapper = byte_wrapper_type(
                cursor_variable_buffer, 1, len(cursor_variable_encoded)
            )
            cursor_variable.encode(cursor_variable_wrapper)
            self.assertEqual(
                cursor_variable_wrapper.getPos(), 1 + len(cursor_variable_encoded)
            )
            decoded_cursor_variable = raw_encoder.createHLAvariableArray(
                variable_factory,
                jpype.JArray(data_element_type)([]),
            )
            decode_cursor_variable_wrapper = byte_wrapper_type(
                cursor_variable_buffer, 1, len(cursor_variable_encoded)
            )
            decoded_cursor_variable.decode(decode_cursor_variable_wrapper)
            self.assertEqual(decoded_cursor_variable.size(), 2)
            self.assertEqual(decoded_cursor_variable.get(0).getValue(), 11)
            self.assertEqual(decoded_cursor_variable.get(1).getValue(), -12)
            self.assertEqual(decode_cursor_variable_wrapper.remaining(), 0)

            # HLAvariableArray's exact Java 2025 ``resize`` method is a
            # provider-scoped extension; the shared Python contract keeps the
            # portable append-only operation.
            cursor_variable.resize(3)
            self.assertEqual(cursor_variable.size(), 3)
            python_variable = python_encoder.createHLAvariableArray(
                _Integer32ElementFactory(python_encoder)
            )
            self.assertIs(python_variable.resize(2), python_variable)
            self.assertEqual(python_variable.size(), 2)
            python_variable.decode(cursor_variable_encoded)
            self.assertEqual(python_variable.toByteArray(), cursor_variable_encoded)

            # Composite decoders must reject malformed child/count payloads
            # with the standard Java DecoderException, not a generic RTI
            # failure.  These inputs are deliberately shorter than the
            # C++-declared fixed record/fixed array and variable-array count.
            malformed_record = raw_encoder.createHLAfixedRecord()
            malformed_record.appendElement(raw_encoder.createHLAinteger32BE())
            malformed_record.appendElement(raw_encoder.createHLAoctet())
            with self.assertRaises(java_decoder_exception):
                malformed_record.decode(
                    byte_wrapper_type(
                        jpype.JArray(jpype.JByte)([0, 0, 0, 1]), 0, 4
                    )
                )
            malformed_fixed = raw_encoder.createHLAfixedArray(
                jpype.JArray(data_element_type)(
                    [raw_encoder.createHLAinteger32BE(), raw_encoder.createHLAinteger32BE()]
                )
            )
            with self.assertRaises(java_decoder_exception):
                malformed_fixed.decode(
                    byte_wrapper_type(
                        jpype.JArray(jpype.JByte)([0, 0, 0, 1, 0, 0]), 0, 6
                    )
                )
            with self.assertRaises(java_decoder_exception):
                raw_encoder.createHLAvariableArray(
                    variable_factory,
                    jpype.JArray(data_element_type)([]),
                ).decode(
                    byte_wrapper_type(
                        jpype.JArray(jpype.JByte)([0, 0, 0, 2, 0, 0, 0, 1]),
                        0,
                        8,
                    )
                )

            # Exercise the standard varargs fixed-array overload as a Java
            # array, rather than the Python façade's factory/size adaptation.
            data_element_type = jpype.JClass("hla.rti1516_2025.encoding.DataElement")
            fixed_values = jpype.JArray(data_element_type)(
                [raw_encoder.createHLAinteger32BE(1), raw_encoder.createHLAinteger32BE(2)]
            )
            fixed_array = raw_encoder.createHLAfixedArray(fixed_values)
            fixed_encoded = bytes(fixed_array.toByteArray())
            self.assertEqual(fixed_array.getEncodedLength(), len(fixed_encoded))
            self.assertEqual(fixed_array.get(0).getValue(), 1)
            self.assertEqual(fixed_array.get(1).getValue(), 2)

            # The provider-scoped Python façade also exposes Java's exact
            # fixed-array varargs overload.  The shared factory/size form
            # remains available for provider-neutral callers.
            python_fixed_array = python_encoder.createHLAfixedArray(
                python_encoder.createHLAinteger32BE(1),
                python_encoder.createHLAinteger32BE(2),
            )
            self.assertEqual(python_fixed_array.getEncodedLength(), len(fixed_encoded))
            self.assertEqual(python_fixed_array.toByteArray(), fixed_encoded)
            self.assertEqual(python_fixed_array.get(0).getValue(), 1)
            self.assertEqual(python_fixed_array.get(1).getValue(), 2)

            # The Java 2025 extendable-variant interface has no explicit
            # addVariant operation.  The JNI carrier registers the first
            # setVariant mapping in C++ and preserves it for decode.
            discriminant_prototype = raw_encoder.createHLAoctet()
            extendable = raw_encoder.createHLAextendableVariantRecord(
                discriminant_prototype
            )
            discriminant_value = raw_encoder.createHLAoctet(3)
            variant_value = raw_encoder.createHLAinteger32BE(0x01020304)
            extendable.setVariant(discriminant_value, variant_value)
            self.assertEqual(extendable.getDiscriminant().getValue(), 3)
            self.assertEqual(extendable.getValue().getValue(), 0x01020304)
            extendable_encoded = bytes(extendable.toByteArray())
            decoded_extendable = raw_encoder.createHLAextendableVariantRecord(
                raw_encoder.createHLAoctet()
            )
            decoded_extendable.setVariant(
                raw_encoder.createHLAoctet(3), raw_encoder.createHLAinteger32BE()
            )
            decoded_extendable.decode(extendable_encoded)
            self.assertEqual(decoded_extendable.getDiscriminant().getValue(), 3)
            self.assertEqual(decoded_extendable.getValue().getValue(), 0x01020304)

            # The dynamic Java carrier must remain a standard DataElement when
            # nested in another standard Java composite.  JNI clones the
            # extendable C++ element instead of attempting a Java re-encode.
            nested_record = raw_encoder.createHLAfixedRecord()
            nested_record.appendElement(extendable)
            nested_record_encoded = bytes(nested_record.toByteArray())
            decoded_nested_record = raw_encoder.createHLAfixedRecord()
            nested_prototype = raw_encoder.createHLAextendableVariantRecord(
                raw_encoder.createHLAoctet()
            )
            nested_prototype.setVariant(
                raw_encoder.createHLAoctet(3), raw_encoder.createHLAinteger32BE()
            )
            decoded_nested_record.appendElement(nested_prototype)
            decoded_nested_record.decode(nested_record_encoded)
            nested_value = decoded_nested_record.get(0)
            self.assertEqual(nested_value.getDiscriminant().getValue(), 3)
            self.assertEqual(nested_value.getValue().getValue(), 0x01020304)

            python_extendable = python_encoder.createHLAextendableVariantRecord(
                python_encoder.createHLAoctet()
            )
            python_extendable.setVariant(
                python_encoder.createHLAoctet(3),
                python_encoder.createHLAinteger32BE(0x01020304),
            )
            self.assertEqual(
                python_extendable.getDiscriminant().getValue(),
                discriminant_value.getValue(),
            )
            self.assertEqual(python_extendable.getValue().getValue(), 0x01020304)
            self.assertEqual(python_extendable.toByteArray(), extendable_encoded)
            decoded_python_extendable = python_encoder.createHLAextendableVariantRecord(
                python_encoder.createHLAoctet()
            )
            decoded_python_extendable.setVariant(
                python_encoder.createHLAoctet(3),
                python_encoder.createHLAinteger32BE(),
            )
            decoded_python_extendable.decode(extendable_encoded)
            self.assertEqual(decoded_python_extendable.getDiscriminant().getValue(), 3)
            self.assertEqual(decoded_python_extendable.getValue().getValue(), 0x01020304)

            time_factory = raw_ambassador.getTimeFactory()
            time_value = time_factory.makeInitial()
            time_element = raw_encoder.createHLAlogicalTime(raw_ambassador, time_value)
            time_encoded = bytes(time_element.toByteArray())
            self.assertEqual(time_element.getEncodedLength(), len(time_encoded))
            decoded_time = raw_encoder.createHLAlogicalTime(raw_ambassador)
            decoded_time.decode(time_encoded)
            self.assertTrue(time_value.equals(decoded_time.getValue()))

            interval_value = time_factory.makeEpsilon()
            interval_element = raw_encoder.createHLAlogicalTimeInterval(
                raw_ambassador, interval_value
            )
            interval_encoded = bytes(interval_element.toByteArray())
            self.assertEqual(interval_element.getEncodedLength(), len(interval_encoded))
            decoded_interval = raw_encoder.createHLAlogicalTimeInterval(raw_ambassador)
            decoded_interval.decode(interval_encoded)
            self.assertTrue(interval_value.equals(decoded_interval.getValue()))

            # The same provider-scoped Python façade preserves the exact
            # Java logical-time creator overloads.  C++ remains responsible
            # for the encoded value and Java remains the carrier boundary.
            python_time_factory = ambassador.getTimeFactory()
            python_time = python_time_factory.makeInitial()
            python_time_element = python_encoder.createHLAlogicalTime(
                ambassador, python_time
            )
            self.assertEqual(python_time_element.toByteArray(), time_encoded)
            self.assertEqual(python_time_element.getValue(), python_time)
            decoded_python_time = python_encoder.createHLAlogicalTime(ambassador)
            decoded_python_time.decode(time_encoded)
            self.assertEqual(decoded_python_time.getValue(), python_time)

            python_interval = python_time_factory.makeEpsilon()
            python_interval_element = python_encoder.createHLAlogicalTimeInterval(
                ambassador, python_interval
            )
            self.assertEqual(python_interval_element.toByteArray(), interval_encoded)
            self.assertEqual(python_interval_element.getValue(), python_interval)
            decoded_python_interval = python_encoder.createHLAlogicalTimeInterval(
                ambassador
            )
            decoded_python_interval.decode(interval_encoded)
            self.assertEqual(decoded_python_interval.getValue(), python_interval)
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.DELETE_OBJECTS)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
                ambassador.disconnect()
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_federation_lifecycle_error_mapping(self) -> None:
        """Federation lifecycle errors retain their C++ standard exception names."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-lifecycle-errors-{uuid4()}"
        missing_federation = f"python-jni-missing-{uuid4()}"
        invalid_fom = fom_module.with_name(f"missing-{uuid4()}.xml")
        creator = self.factory.getRtiAmbassador()
        joiner = self.factory.getRtiAmbassador()
        creator_callbacks = _JniCallbacks()
        joiner_callbacks = _JniCallbacks()
        creator_connected = False
        joiner_connected = False
        creator_joined = False
        joiner_joined = False
        try:
            creator.connect(creator_callbacks, CallbackModel.HLA_EVOKED)
            creator_connected = True
            joiner.connect(joiner_callbacks, CallbackModel.HLA_EVOKED)
            joiner_connected = True

            with self.assertRaises(FederationExecutionDoesNotExist):
                creator.destroyFederationExecution(missing_federation)
            with self.assertRaises(CouldNotOpenFOM):
                creator.createFederationExecution(
                    f"python-jni-invalid-fom-{uuid4()}",
                    str(invalid_fom),
                    "HLAinteger64Time",
                )

            # The Restaurant FOM declares HLAinteger64Time.  The standard
            # create overload with an empty implementation name selects the
            # C++ default and must reject that inconsistent definition without
            # reserving the federation name.
            inconsistent_federation = f"python-jni-inconsistent-{uuid4()}"
            with self.assertRaises(InconsistentFOM):
                creator.createFederationExecution(
                    inconsistent_federation, str(fom_module), ""
                )
            with self.assertRaises(FederationExecutionDoesNotExist):
                creator.destroyFederationExecution(inconsistent_federation)

            creator.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            with self.assertRaises(FederationExecutionAlreadyExists):
                joiner.createFederationExecution(
                    federation_name, str(fom_module), "HLAinteger64Time"
                )

            creator.joinFederationExecution(
                "jni-lifecycle-owner",
                federation_name,
                federateName="jni-lifecycle-owner",
            )
            creator_joined = True
            with self.assertRaises(FederateAlreadyExecutionMember):
                creator.joinFederationExecution(
                    "jni-lifecycle-owner-again",
                    federation_name,
                    federateName="jni-lifecycle-owner",
                )
            with self.assertRaises(FederateNameAlreadyInUse):
                joiner.joinFederationExecution(
                    "jni-lifecycle-duplicate",
                    federation_name,
                    federateName="jni-lifecycle-owner",
                )
            joiner.joinFederationExecution(
                "jni-lifecycle-joiner",
                federation_name,
                federateName="jni-lifecycle-joiner",
            )
            joiner_joined = True

            with self.assertRaises(FederatesCurrentlyJoined):
                creator.destroyFederationExecution(federation_name)

            creator.resignFederationExecution(ResignAction.NO_ACTION)
            creator_joined = False
            # Federate Resigned is an RTI-originated callback.  A normal
            # federate-initiated resign must not echo that callback to the
            # resigning federate or fabricate one for the surviving member.
            for _ in range(20):
                creator.evokeCallback(0.0)
                joiner.evokeCallback(0.0)
            self.assertEqual(creator_callbacks.federate_resigned, [])
            self.assertEqual(joiner_callbacks.federate_resigned, [])
            joiner.resignFederationExecution(ResignAction.NO_ACTION)
            joiner_joined = False
            creator.destroyFederationExecution(federation_name)
            with self.assertRaises(FederationExecutionDoesNotExist):
                joiner.joinFederationExecution(
                    "jni-lifecycle-after-destroy",
                    federation_name,
                    federateName="jni-lifecycle-after-destroy",
                )
        finally:
            if creator_connected:
                try:
                    if creator_joined:
                        creator.resignFederationExecution(ResignAction.NO_ACTION)
                    creator.disconnect()
                except Exception:
                    pass
            if joiner_connected:
                try:
                    if joiner_joined:
                        joiner.resignFederationExecution(ResignAction.NO_ACTION)
                    joiner.disconnect()
                except Exception:
                    pass
            creator._implementation.close()
            joiner._implementation.close()

    def test_cpp_jni_java_jpype_join_fom_seeds_advisory_switches_per_member(
        self,
    ) -> None:
        """Keep join-time composed-FDD switch defaults scoped to the new member."""
        base_fom = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-nrg-disabled-fom.xml"
        )
        advisory_fom = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-join-fom-switches-{uuid4()}"
        base = self.factory.getRtiAmbassador()
        extension = self.factory.getRtiAmbassador()
        base_callbacks = _JniCallbacks()
        extension_callbacks = _JniCallbacks()
        base_connected = extension_connected = False
        base_joined = extension_joined = created = False
        try:
            base.connect(base_callbacks, CallbackModel.HLA_EVOKED)
            base_connected = True
            extension.connect(extension_callbacks, CallbackModel.HLA_EVOKED)
            extension_connected = True
            base.createFederationExecution(
                federation_name, str(base_fom), "HLAinteger64Time"
            )
            created = True
            base.joinFederationExecution(
                "switch-base",
                federation_name,
                federateName="switch-base",
            )
            base_joined = True
            self.assertFalse(base.getObjectClassRelevanceAdvisorySwitch())
            self.assertFalse(base.getInteractionRelevanceAdvisorySwitch())

            extension.joinFederationExecution(
                "switch-extension",
                federation_name,
                federateName="switch-extension",
                additionalFomModules=[str(advisory_fom)],
            )
            extension_joined = True
            self.assertTrue(extension.getObjectClassRelevanceAdvisorySwitch())
            self.assertTrue(extension.getInteractionRelevanceAdvisorySwitch())
            self.assertFalse(base.getObjectClassRelevanceAdvisorySwitch())
            self.assertFalse(base.getInteractionRelevanceAdvisorySwitch())
        finally:
            if extension_joined:
                try:
                    extension.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if base_joined:
                try:
                    base.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    base.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, connected in (
                (extension, extension_connected),
                (base, base_connected),
            ):
                if connected:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

    def test_cpp_jni_java_jpype_federate_lookup_preserves_departed_designator(
        self,
    ) -> None:
        """Keep a departed member's federate-name identity through Java/JPype."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-federate-lookup-{uuid4()}"
        foreign_federation_name = f"python-jni-federate-lookup-foreign-{uuid4()}"
        unjoined = self.factory.getRtiAmbassador()
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        foreign_creator = self.factory.getRtiAmbassador()
        foreign_member = self.factory.getRtiAmbassador()
        callbacks = [
            _JniCallbacks(),
            _JniCallbacks(),
            _JniCallbacks(),
            _JniCallbacks(),
            _JniCallbacks(),
        ]
        ambassadors = [unjoined, owner, peer, foreign_creator, foreign_member]
        connected = [False] * len(ambassadors)
        joined = [False] * len(ambassadors)
        created = [False, False]

        try:
            unknown_federate = FederateHandle(b"\x00\x00\x00\x08" + b"\x00" * 8)
            with self.assertRaises(NotConnected):
                unjoined.getFederateHandle("jni-lookup-owner")
            with self.assertRaises(NotConnected):
                unjoined.getFederateName(unknown_federate)

            for index, ambassador in enumerate(ambassadors):
                ambassador.connect(callbacks[index], CallbackModel.HLA_EVOKED)
                connected[index] = True

            with self.assertRaises(FederateNotExecutionMember):
                unjoined.getFederateHandle("jni-lookup-owner")
            with self.assertRaises(FederateNotExecutionMember):
                unjoined.getFederateName(unknown_federate)

            owner.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created[0] = True
            foreign_creator.createFederationExecution(
                foreign_federation_name, str(fom_module), "HLAinteger64Time"
            )
            created[1] = True

            owner_handle = owner.joinFederationExecution(
                "jni-federate-lookup-owner",
                federation_name,
                federateName="jni-federate-lookup-owner",
            )
            joined[1] = True
            peer_handle = peer.joinFederationExecution(
                "jni-federate-lookup-peer",
                federation_name,
                federateName="jni-federate-lookup-peer",
            )
            joined[2] = True
            foreign_handle = foreign_member.joinFederationExecution(
                "jni-federate-lookup-foreign",
                foreign_federation_name,
                federateName="jni-federate-lookup-foreign",
            )
            joined[4] = True

            self.assertEqual(
                owner.getFederateHandle("jni-federate-lookup-owner"), owner_handle
            )
            self.assertEqual(
                owner.getFederateHandle("jni-federate-lookup-peer"), peer_handle
            )
            self.assertEqual(peer.getFederateName(owner_handle), "jni-federate-lookup-owner")
            self.assertEqual(peer.getFederateName(peer_handle), "jni-federate-lookup-peer")
            with self.assertRaises(NameNotFound):
                owner.getFederateHandle("jni-no-such-federate")
            with self.assertRaises(InvalidFederateHandle):
                owner.getFederateName(unknown_federate)
            with self.assertRaises(FederateHandleNotKnown):
                owner.getFederateName(foreign_handle)

            peer.resignFederationExecution(ResignAction.NO_ACTION)
            joined[2] = False
            with self.assertRaises(NameNotFound):
                owner.getFederateHandle("jni-federate-lookup-peer")
            self.assertEqual(owner.getFederateName(peer_handle), "jni-federate-lookup-peer")

            foreign_member.resignFederationExecution(ResignAction.NO_ACTION)
            joined[4] = False
            owner.resignFederationExecution(ResignAction.NO_ACTION)
            joined[1] = False
            foreign_creator.destroyFederationExecution(foreign_federation_name)
            created[1] = False
            owner.destroyFederationExecution(federation_name)
            created[0] = False
        finally:
            for index, ambassador in enumerate(ambassadors):
                if joined[index]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if created[0] and connected[1]:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if created[1] and connected[3]:
                try:
                    foreign_creator.destroyFederationExecution(foreign_federation_name)
                except Exception:
                    pass
            for index, ambassador in enumerate(ambassadors):
                if connected[index]:
                    try:
                        ambassador.disconnect()
                    except Exception:
                        pass
                ambassador._implementation.close()

    def test_cpp_jni_java_jpype_membership_reentry_rejects_callback_call(self) -> None:
        """Membership services reject re-entrant join and resign calls."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-membership-reentry-{uuid4()}"

        class _ReentrantCallbacks(FederateAmbassador):
            def __init__(self) -> None:
                self.ambassador: RTIambassador | None = None
                self.errors: list[Exception] = []

            def reportFederationExecutions(
                self, report: FederationExecutionInformationSet
            ) -> None:
                del report
                assert self.ambassador is not None
                try:
                    self.ambassador.connect(self, CallbackModel.HLA_EVOKED)
                except Exception as error:
                    self.errors.append(error)
                try:
                    self.ambassador.disconnect()
                except Exception as error:
                    self.errors.append(error)
                try:
                    self.ambassador.joinFederationExecution(
                        "jni-reentrant-join-type", federation_name
                    )
                except Exception as error:
                    self.errors.append(error)
                try:
                    self.ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception as error:
                    self.errors.append(error)

        ambassador = self.factory.getRtiAmbassador()
        callbacks = _ReentrantCallbacks()
        connected = joined = created = False
        try:
            callbacks.ambassador = ambassador
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-membership-reentry-type",
                federation_name,
                federateName="jni-membership-reentry",
            )
            joined = True

            ambassador.listFederationExecutions()
            ambassador.evokeCallback(0.0)
            self.assertEqual(len(callbacks.errors), 4)
            self.assertIsInstance(callbacks.errors[0], CallNotAllowedFromWithinCallback)
            self.assertIsInstance(callbacks.errors[1], CallNotAllowedFromWithinCallback)
            self.assertIsInstance(callbacks.errors[2], CallNotAllowedFromWithinCallback)
            self.assertIsInstance(callbacks.errors[3], CallNotAllowedFromWithinCallback)

            # The failed callback attempt must not poison the membership
            # lifecycle; the same proxy can still resign normally afterward.
            ambassador.resignFederationExecution(ResignAction.NO_ACTION)
            joined = False
        finally:
            if joined:
                try:
                    ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    ambassador.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if connected:
                try:
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_federation_services_require_connection(self) -> None:
        """Preserve C++ NotConnected across the exact standard Java lifecycle calls."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        mim_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "mim"
            / "HLAstandardMIM-2025.xml"
        )
        federation_name = f"python-jni-not-connected-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        raw = ambassador.unwrap_java_object()
        java_not_connected = jpype.JClass(
            "hla.rti1516_2025.exceptions.NotConnected"
        )
        try:
            # These are the standard Java overloads, including the iterable
            # String[] and create-with-MIM forms.  The C++ ambassador rejects
            # them before it can inspect the FOM, so every route must retain
            # the same typed NotConnected exception.
            with self.assertRaises(java_not_connected):
                raw.createFederationExecution(
                    federation_name, str(fom_module), "HLAinteger64Time"
                )
            with self.assertRaises(java_not_connected):
                raw.createFederationExecution(
                    f"{federation_name}-vector", [str(fom_module)]
                )
            with self.assertRaises(java_not_connected):
                raw.createFederationExecutionWithMIM(
                    f"{federation_name}-mim",
                    [str(fom_module)],
                    str(mim_module),
                )
            with self.assertRaises(java_not_connected):
                raw.destroyFederationExecution(federation_name)
            with self.assertRaises(java_not_connected):
                raw.joinFederationExecution("jni-not-connected-observer", federation_name)
            with self.assertRaises(java_not_connected):
                raw.resignFederationExecution(
                    jpype.JClass("hla.rti1516_2025.ResignAction").NO_ACTION
                )
        finally:
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_transport_loss_connection_and_membership_callbacks(
        self,
    ) -> None:
        """Exercise C++ transport-loss cleanup through the standard Java callback."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        # Keep the generated report pathname below Windows' legacy MAX_PATH;
        # the service-report filename already includes federate/federation IDs.
        federation_name = f"jni-cl-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / "cl-reports"
        lost = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        lost_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        lost_connected = survivor_connected = created = False
        lost_joined = survivor_joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = RtiConfiguration.createConfiguration().withAdditionalSettings(
                f"serviceReportDirectory={reports_directory}"
            )
            lost.connect(lost_callbacks, CallbackModel.HLA_EVOKED, configuration)
            lost_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            lost.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            lost.joinFederationExecution(
                "jni-lost", federation_name, federateName="jni-lost"
            )
            lost_joined = True
            survivor.joinFederationExecution(
                "jni-survivor",
                federation_name,
                federateName="jni-survivor",
            )
            survivor_joined = True

            report_files = sorted(reports_directory.glob("*"))
            self.assertEqual(len(report_files), 1)
            report_file = report_files[0]
            initial_report = report_file.read_text(encoding="utf-8")

            # The control is intentionally package-private and test-only; the
            # actual callback and all observable state transitions are the
            # standard Java API surface.  Reflection keeps this hook out of
            # the public RTIambassador contract.
            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass(
                "hla.rti1516_2025.RTIambassador"
            ).class_
            string_class = jpype.JClass("java.lang.String").class_
            fault_method = native_handler_class.getDeclaredMethod(
                "failEmbeddedTransportConnectionForTesting",
                rti_interface_class,
                string_class,
            )
            fault_method.setAccessible(True)
            fault = "embedded loopback transport closed"
            self.assertTrue(
                bool(fault_method.invoke(None, lost.unwrap_java_object(), fault))
            )

            # The C++ RTI service record is durable before the callback is
            # delivered, matching the embedded service-report contract.
            report_after_control = report_file.read_text(encoding="utf-8")
            self.assertGreater(len(report_after_control), len(initial_report))
            self.assertIn('"HLAservice":"ConnectionLost"', report_after_control)
            self.assertIn('"HLAargumentName":"Fault description"', report_after_control)
            self.assertIn('"HLAargumentValue":"embedded loopback transport closed"', report_after_control)

            self.assertFalse(lost.evokeCallback(0.0))
            self.assertEqual(lost_callbacks.connection_lost, [fault])
            # `disconnect` is a no-throws service in the exact Java standard;
            # the Java adapter intentionally absorbs C++ NotConnected here.
            lost.disconnect()
            with self.assertRaises(NotConnected):
                lost.joinFederationExecution("jni-after-transport-loss", federation_name)

            survivor.listFederationExecutionMembers(federation_name)
            survivor.evokeCallback(0.0)
            self.assertEqual(
                survivor_callbacks.member_reports[-1][1],
                FederationExecutionMemberInformationSet(
                    {FederationExecutionMemberInformation(
                        "jni-survivor", "jni-survivor"
                    )}
                ),
            )
        finally:
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    survivor.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            if lost_connected:
                try:
                    lost.disconnect()
                except Exception:
                    pass
            lost._implementation.close()
            survivor._implementation.close()

