            survivor_attributes = AttributeHandleSet([survivor_efficiency])
            departing.publishObjectClassAttributes(departing_class, departing_attributes)
            departing.subscribeObjectClassAttributes(departing_class, departing_attributes)
            survivor.publishObjectClassAttributes(survivor_class, survivor_attributes)
            survivor.subscribeObjectClassAttributes(survivor_class, survivor_attributes)

            # Transfer one attribute onto the federate that will later resign;
            # its combined directive must divest this object without deleting it.
