    def test_cpp_jni_java_jpype_forced_resignation_callback_and_rejoin(self) -> None:
        """Exercise RTI-originated Federate Resigned through exact Java callbacks."""
        import jpype

        fom_module = (
            Path(__file__).parents[3]
            / "cpp"
            / "tests"
            / "data"
            / "switch-support-enabled-fom.xml"
        )
        # Keep the generated report pathname below Windows' legacy MAX_PATH;
        # the service-report filename already includes federate/federation IDs.
        federation_name = f"jni-fr-{uuid4().hex[:12]}"
        reports_directory = self._temporary_directory / "fr-reports"
        forced = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        forced_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        forced_connected = survivor_connected = created = False
        forced_joined = survivor_joined = False
        try:
            reports_directory.mkdir(parents=True, exist_ok=True)
            configuration = RtiConfiguration.createConfiguration().withAdditionalSettings(
                f"serviceReportDirectory={reports_directory}"
            )
            forced.connect(forced_callbacks, CallbackModel.HLA_EVOKED, configuration)
            forced_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            forced.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            forced.joinFederationExecution(
                "jni-forced-resignation",
                federation_name,
                federateName="jni-forced-resignation",
            )
            forced_joined = True
            survivor.joinFederationExecution(
                "jni-forced-survivor",
                federation_name,
                federateName="jni-forced-survivor",
            )
            survivor_joined = True

            report_files = sorted(reports_directory.glob("*"))
            self.assertEqual(len(report_files), 1)
            report_file = report_files[0]
            initial_report = report_file.read_text(encoding="utf-8")

            # This package-private helper is only a deterministic C++ test
            # input.  The callback and all state assertions use the exact
            # standard Java API loaded from the external IEEE JAR.
            native_handler_class = jpype.JClass("java.lang.Class").forName(
                "org.umbra.jni.rti1516_2025.NativeRTIambassador"
            )
            rti_interface_class = jpype.JClass(
                "hla.rti1516_2025.RTIambassador"
            ).class_
            string_class = jpype.JClass("java.lang.String").class_
            resign_method = native_handler_class.getDeclaredMethod(
                "forceEmbeddedFederateResignationForTesting",
                rti_interface_class,
                string_class,
            )
            resign_method.setAccessible(True)
            reason = "embedded RTI membership control removed this federate"
            self.assertTrue(
                bool(resign_method.invoke(None, forced.unwrap_java_object(), reason))
            )
            forced_joined = False

            # The C++ RTI service record is durable before the callback is
            # delivered, matching the embedded service-report contract.
            report_after_control = report_file.read_text(encoding="utf-8")
            self.assertGreater(len(report_after_control), len(initial_report))
            self.assertIn('"HLAservice":"FederateResigned"', report_after_control)
            self.assertIn('"HLAargumentName":"Reason for resigning"', report_after_control)
            self.assertIn(
                '"HLAargumentValue":"embedded RTI membership control removed this federate"',
                report_after_control,
            )

            self.assertFalse(forced.evokeCallback(0.0))
            self.assertEqual(forced_callbacks.federate_resigned, [reason])
            self.assertEqual(survivor_callbacks.federate_resigned, [])

            survivor.listFederationExecutionMembers(federation_name)
            survivor.evokeCallback(0.0)
            self.assertEqual(
                survivor_callbacks.member_reports[-1][1],
                FederationExecutionMemberInformationSet(
                    {FederationExecutionMemberInformation(
                        "jni-forced-survivor", "jni-forced-survivor"
                    )}
                ),
            )
            self.assertFalse(
                bool(resign_method.invoke(None, forced.unwrap_java_object(), "duplicate"))
            )

            # RTI-originated resignation ends membership but deliberately
            # keeps the Java/C++ connection alive; the same proxy can rejoin.
            forced.joinFederationExecution(
                "jni-forced-rejoined",
                federation_name,
                federateName="jni-forced-rejoined",
            )
            forced_joined = True
            forced.resignFederationExecution(ResignAction.NO_ACTION)
            forced_joined = False
        finally:
            if forced_joined:
                try:
                    forced.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_joined:
                try:
                    survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    forced.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if forced_connected:
                try:
                    forced.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            forced._implementation.close()
            survivor._implementation.close()

