    def test_cpp_jni_java_jpype_resign_action_membership_matrix(self) -> None:
        """Preserve every standard ResignAction across the JNI membership path."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-resign-actions-{uuid4()}"
        extension_federation_name = f"{federation_name}-extension"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = extension_created = joined = False

        def observe_members(expected: FederationExecutionMemberInformationSet) -> None:
            before = len(callbacks.member_reports)
            ambassador.listFederationExecutionMembers(federation_name)
            for _ in range(20):
                ambassador.evokeCallback(0.0)
                if len(callbacks.member_reports) > before:
                    break
            self.assertGreater(len(callbacks.member_reports), before)
            self.assertEqual(callbacks.member_reports[-1], (federation_name, expected))

        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            # Invoke the official Java two-argument overloads directly once.
            # The public Python adapter normally supplies the optional logical
            # time name, so this keeps the Java-only overloads observable too.
            import jpype

            raw_ambassador = ambassador.unwrap_java_object()
            raw_federation_name = f"{federation_name}-raw-java"
            raw_fom_module = (
                Path(__file__).parents[3]
                / "cpp"
                / "tests"
                / "data"
                / "switch-support-enabled-fom.xml"
            )
            raw_fom_modules = jpype.JArray(jpype.JString)([str(raw_fom_module)])
            raw_ambassador.createFederationExecution(
                raw_federation_name, raw_fom_modules
            )
            raw_handle = raw_ambassador.joinFederationExecution(
                "jni-raw-unnamed-type", raw_federation_name
            )
            self.assertGreater(raw_handle.encodedLength(), 0)
            raw_ambassador.resignFederationExecution(
                jpype.JClass("hla.rti1516_2025.ResignAction").NO_ACTION
            )
            raw_ambassador.destroyFederationExecution(raw_federation_name)
            raw_string_federation_name = f"{federation_name}-raw-string"
            raw_ambassador.createFederationExecution(
                raw_string_federation_name, str(raw_fom_module)
            )
            raw_string_handle = raw_ambassador.joinFederationExecution(
                "jni-raw-string", raw_string_federation_name
            )
            self.assertGreater(raw_string_handle.encodedLength(), 0)
            raw_ambassador.resignFederationExecution(
                jpype.JClass("hla.rti1516_2025.ResignAction").NO_ACTION
            )
            raw_ambassador.destroyFederationExecution(raw_string_federation_name)
            raw_mim_module = (
                Path(__file__).parents[3]
                / "third_party"
                / "ieee1516.2-2025"
                / "resources"
                / "mim"
                / "HLAstandardMIM-2025.xml"
            )
            raw_mim_federation_name = f"{federation_name}-raw-mim"
            raw_ambassador.createFederationExecutionWithMIM(
                raw_mim_federation_name,
                raw_fom_modules,
                str(raw_mim_module),
            )
            raw_ambassador.destroyFederationExecution(raw_mim_federation_name)

            extension_module = (
                Path(__file__).parents[3]
                / "cpp"
                / "tests"
                / "data"
                / "reference-data-class-provider-fom.xml"
            )
            ambassador.createFederationExecution(
                extension_federation_name,
                [str(fom_module)],
                "HLAinteger64Time",
            )
            extension_created = True

            # Passing an iterable keeps the Python adapter on the exact
            # standard Java String[] createFederationExecution overload.
            ambassador.createFederationExecution(
                federation_name, [str(fom_module)], "HLAinteger64Time"
            )
            created = True
            ambassador.listFederationExecutions()
            for _ in range(20):
                ambassador.evokeCallback(0.0)
                if callbacks.execution_reports:
                    break
            self.assertIn(
                FederationExecutionInformation(
                    extension_federation_name, "HLAinteger64Time"
                ),
                callbacks.execution_reports[-1],
            )
            self.assertIn(
                FederationExecutionInformation(federation_name, "HLAinteger64Time"),
                callbacks.execution_reports[-1],
            )

            for index, resign_action in enumerate(ResignAction):
                if index == 0:
                    # Exercise the Python adapter's unnamed-join overload as
                    # well as the direct Java call above.  The C++ registry
                    # assigns the name, which must round-trip through the
                    # standard federate-handle lookup service.
                    federate_handle = ambassador.joinFederationExecution(
                        "jni-resign-type", federation_name
                    )
                    federate_name = ambassador.getFederateName(federate_handle)
                    self.assertTrue(federate_name)
                else:
                    federate_name = f"jni-resign-{index}"
                    join_kwargs: dict[str, object] = {"federateName": federate_name}
                    if index == 1:
                        # Supply a compatible extension at join time so the
                        # Java String[] join overload must materialize its
                        # additional class catalog.
                        join_kwargs["additionalFomModules"] = [str(extension_module)]
                    federate_handle = ambassador.joinFederationExecution(
                        "jni-resign-type", federation_name, **join_kwargs
                    )
                    if index == 1:
                        extension_handle = ambassador.getObjectClassHandle(
                            "HLAobjectRoot.UmbraReferenceFixtureClass"
                        )
                        self.assertGreater(extension_handle.encodedLength(), 0)
                joined = True
                self.assertGreater(federate_handle.encodedLength(), 0)
                observe_members(
                    FederationExecutionMemberInformationSet(
                        {FederationExecutionMemberInformation(federate_name, "jni-resign-type")}
                    )
                )
                if index == 0:
                    with self.assertRaises(FederateIsExecutionMember):
                        ambassador.disconnect()

                ambassador.resignFederationExecution(resign_action)
                joined = False
                # A normal resignation removes membership without fabricating
                # the RTI-originated federateResigned callback.
                self.assertEqual(callbacks.federate_resigned, [])
                observe_members(FederationExecutionMemberInformationSet())

            ambassador.destroyFederationExecution(federation_name)
            created = False
        finally:
            if connected:
                try:
                    if joined:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    if created:
                        ambassador.destroyFederationExecution(federation_name)
                    if extension_created:
                        ambassador.destroyFederationExecution(extension_federation_name)
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_resign_delete_objects_notifies_survivor(self) -> None:
        """Route DELETE_OBJECTS resignation cleanup through the standard callback."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-resign-delete-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        survivor = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        survivor_callbacks = _JniCallbacks()
        owner_connected = survivor_connected = created = False
        owner_joined = survivor_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                survivor.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            survivor.connect(survivor_callbacks, CallbackModel.HLA_EVOKED)
            survivor_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            owner_handle = owner.joinFederationExecution(
                "jni-resign-delete-owner",
                federation_name,
                federateName="jni-resign-delete-owner",
            )
            owner_joined = True
            survivor.joinFederationExecution(
                "jni-resign-delete-survivor",
                federation_name,
                federateName="jni-resign-delete-survivor",
            )
            survivor_joined = True

            owner_class = owner.getObjectClassHandle("HLAobjectRoot.Employee.Server")
            survivor_class = survivor.getObjectClassHandle(
                "HLAobjectRoot.Employee.Server"
            )
            owner_attribute = owner.getAttributeHandle(owner_class, "Efficiency")
            survivor_attribute = survivor.getAttributeHandle(
                survivor_class, "Efficiency"
            )
            owner.publishObjectClassAttributes(
                owner_class, AttributeHandleSet([owner_attribute])
            )
            survivor.subscribeObjectClassAttributes(
                survivor_class, AttributeHandleSet([survivor_attribute]), active=True
            )

            instance = owner.registerObjectInstance(owner_class)
            instance_name = owner.getObjectInstanceName(instance)
            for _ in range(20):
                drain(1)
                if survivor_callbacks.discovered_objects:
                    break
            self.assertEqual(survivor_callbacks.discovered_objects[-1][0], instance)
            self.assertEqual(survivor_callbacks.discovered_objects[-1][3], owner_handle)

            owner.resignFederationExecution(ResignAction.DELETE_OBJECTS)
            owner_joined = False
            for _ in range(20):
                drain(1)
                if survivor_callbacks.removed_objects:
                    break
            self.assertEqual(
                survivor_callbacks.removed_objects,
                [(instance, b"", owner_handle)],
            )
            with self.assertRaises(ObjectInstanceNotKnown):
                survivor.getObjectInstanceHandle(instance_name)

            survivor.listFederationExecutionMembers(federation_name)
            for _ in range(20):
                drain(1)
                if survivor_callbacks.member_reports:
                    break
            self.assertEqual(
                survivor_callbacks.member_reports[-1][1],
                FederationExecutionMemberInformationSet(
                    {
                        FederationExecutionMemberInformation(
                            "jni-resign-delete-survivor",
                            "jni-resign-delete-survivor",
                        )
                    }
                ),
            )
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if survivor_connected:
                try:
                    if survivor_joined:
                        survivor.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            if survivor_connected:
                try:
                    survivor.disconnect()
                except Exception:
                    pass
            owner._implementation.close()
            survivor._implementation.close()

    def test_cpp_jni_java_jpype_resign_unconditionally_divests_attributes(
        self,
    ) -> None:
        """Preserve ownership divestiture when a member resigns through Java."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-resign-divest-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        peer = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        peer_callbacks = _JniCallbacks()
        owner_connected = peer_connected = created = False
        owner_joined = peer_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                peer.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            peer.connect(peer_callbacks, CallbackModel.HLA_EVOKED)
            peer_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            owner.joinFederationExecution(
                "jni-resign-divest-owner",
                federation_name,
                federateName="jni-resign-divest-owner",
            )
            owner_joined = True
            peer.joinFederationExecution(
                "jni-resign-divest-peer",
                federation_name,
                federateName="jni-resign-divest-peer",
            )
            peer_joined = True

            owner_class = owner.getObjectClassHandle("HLAobjectRoot.Employee.Server")
            peer_class = peer.getObjectClassHandle("HLAobjectRoot.Employee.Server")
            owner_efficiency = owner.getAttributeHandle(owner_class, "Efficiency")
            peer_efficiency = peer.getAttributeHandle(peer_class, "Efficiency")
            owner_delete_privilege = owner.getAttributeHandle(
                owner_class, "HLAprivilegeToDeleteObject"
            )
            peer_delete_privilege = peer.getAttributeHandle(
                peer_class, "HLAprivilegeToDeleteObject"
            )
            owner_attributes = AttributeHandleSet([owner_efficiency])
            peer_attributes = AttributeHandleSet([peer_efficiency])
            divested_peer_attributes = AttributeHandleSet(
                [peer_efficiency, peer_delete_privilege]
            )
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            peer.subscribeObjectClassAttributes(peer_class, peer_attributes)
            peer.publishObjectClassAttributes(peer_class, peer_attributes)

            instance = owner.registerObjectInstance(owner_class)
            for _ in range(20):
                drain(1)
                if peer_callbacks.discovered_objects:
                    break
            self.assertEqual(peer_callbacks.discovered_objects[-1][0], instance)

            # A no-op resignation cannot strand attributes owned by the
            # departing member; the typed C++ exception must cross JNI first.
            with self.assertRaises(FederateOwnsAttributes):
                owner.resignFederationExecution(ResignAction.NO_ACTION)

            owner.resignFederationExecution(
                ResignAction.UNCONDITIONALLY_DIVEST_ATTRIBUTES
            )
            owner_joined = False
            for _ in range(20):
                drain(1)
                if peer_callbacks.ownership_assumptions:
                    break
            self.assertEqual(
                peer_callbacks.ownership_assumptions,
                [(instance, divested_peer_attributes, b"")],
            )

            acquisition_tag = b"jni-resign-divest-acquire"
            peer.attributeOwnershipAcquisition(instance, peer_attributes, acquisition_tag)
            for _ in range(20):
                drain(1)
                if peer_callbacks.ownership_acquisitions:
                    break
            self.assertEqual(
                peer_callbacks.ownership_acquisitions,
                [(instance, peer_attributes, acquisition_tag)],
            )
            self.assertTrue(peer.isAttributeOwnedByFederate(instance, peer_efficiency))

            peer.resignFederationExecution(
                ResignAction.UNCONDITIONALLY_DIVEST_ATTRIBUTES
            )
            peer_joined = False
            peer.destroyFederationExecution(federation_name)
            created = False
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if peer_connected:
                try:
                    if peer_joined:
                        peer.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if owner_connected:
                try:
                    owner.disconnect()
                except Exception:
                    pass
            if peer_connected:
                try:
                    peer.disconnect()
                except Exception:
                    pass
            owner._implementation.close()
            peer._implementation.close()

    def test_cpp_jni_java_jpype_final_resignation_releases_object_name(self) -> None:
        """Preserve the final-federate forced-delete/name-reuse rule through JNI."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-final-resign-{uuid4()}"
        ambassador = self.factory.getRtiAmbassador()
        callbacks = _JniCallbacks()
        connected = created = joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                ambassador.evokeCallback(0.0)

        try:
            ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            connected = True
            ambassador.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            ambassador.joinFederationExecution(
                "jni-final-resign-owner",
                federation_name,
                federateName="jni-final-resign-owner",
            )
            joined = True
            object_class = ambassador.getObjectClassHandle(
                "HLAobjectRoot.Employee.Server"
            )
            attribute = ambassador.getAttributeHandle(object_class, "Efficiency")
            attributes = AttributeHandleSet([attribute])
            ambassador.publishObjectClassAttributes(object_class, attributes)
            original = ambassador.registerObjectInstance(object_class)
            reusable_name = ambassador.getObjectInstanceName(original)

            # The final member's NO_ACTION resignation is still required to
            # delete its object state before membership is removed.
            ambassador.resignFederationExecution(ResignAction.NO_ACTION)
            joined = False
            ambassador.joinFederationExecution(
                "jni-final-resign-rejoined",
                federation_name,
                federateName="jni-final-resign-rejoined",
            )
            joined = True
            ambassador.publishObjectClassAttributes(object_class, attributes)
            ambassador.reserveObjectInstanceName(reusable_name)
            for _ in range(20):
                drain(1)
                if reusable_name in callbacks.reserved_object_instance_names:
                    break
            self.assertIn(reusable_name, callbacks.reserved_object_instance_names)

            replacement = ambassador.registerObjectInstance(
                object_class, objectInstanceName=reusable_name
            )
            self.assertNotEqual(replacement, original)
            self.assertEqual(
                ambassador.getObjectInstanceName(replacement), reusable_name
            )
            ambassador.resignFederationExecution(ResignAction.NO_ACTION)
            joined = False
            ambassador.destroyFederationExecution(federation_name)
            created = False
        finally:
            if connected:
                try:
                    if joined:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    if created:
                        ambassador.destroyFederationExecution(federation_name)
                    ambassador.disconnect()
                except Exception:
                    pass
            ambassador._implementation.close()

    def test_cpp_jni_java_jpype_resign_rejects_pending_ownership_acquisition(
        self,
    ) -> None:
        """Keep pending-acquisition resignation guards typed through JNI."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-resign-pending-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        requester = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        requester_callbacks = _JniCallbacks()
        owner_connected = requester_connected = created = False
        owner_joined = requester_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                requester.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            requester.connect(requester_callbacks, CallbackModel.HLA_EVOKED)
            requester_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            owner.joinFederationExecution(
                "jni-pending-owner",
                federation_name,
                federateName="jni-pending-owner",
            )
            owner_joined = True
            requester.joinFederationExecution(
                "jni-pending-requester",
                federation_name,
                federateName="jni-pending-requester",
            )
            requester_joined = True

            owner_class = owner.getObjectClassHandle("HLAobjectRoot.Employee.Server")
            requester_class = requester.getObjectClassHandle(
                "HLAobjectRoot.Employee.Server"
            )
            owner_attribute = owner.getAttributeHandle(owner_class, "Efficiency")
            requester_attribute = requester.getAttributeHandle(
                requester_class, "Efficiency"
            )
            owner_attributes = AttributeHandleSet([owner_attribute])
            requester_attributes = AttributeHandleSet([requester_attribute])
            owner.subscribeObjectClassAttributes(owner_class, owner_attributes)
            requester.publishObjectClassAttributes(requester_class, requester_attributes)
            instance = requester.registerObjectInstance(requester_class)
            for _ in range(20):
                drain(1)
                if owner_callbacks.discovered_objects:
                    break
            self.assertEqual(owner_callbacks.discovered_objects[-1][0], instance)

            # Make the owner a valid candidate, then leave its request pending
            # against the requester-owned object.
            owner.publishObjectClassAttributes(owner_class, owner_attributes)
            acquisition_tag = b"jni-pending-resignation"
            owner.attributeOwnershipAcquisition(
                instance, owner_attributes, acquisition_tag
            )
            with self.assertRaises(OwnershipAcquisitionPending):
                owner.resignFederationExecution(
                    ResignAction.UNCONDITIONALLY_DIVEST_ATTRIBUTES
                )

            owner.resignFederationExecution(
                ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST
            )
            owner_joined = False
            requester.resignFederationExecution(ResignAction.DELETE_OBJECTS)
            requester_joined = False
            requester.destroyFederationExecution(federation_name)
            created = False
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                    owner.disconnect()
                except Exception:
                    pass
            if requester_connected:
                try:
                    if requester_joined:
                        requester.resignFederationExecution(ResignAction.NO_ACTION)
                    requester.disconnect()
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            owner._implementation.close()
            requester._implementation.close()

    def test_cpp_jni_java_jpype_resignation_fails_active_save(self) -> None:
        """Preserve FEDERATE_RESIGNED_DURING_SAVE through the Java callback path."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-resign-save-{uuid4()}"
        owner = self.factory.getRtiAmbassador()
        resigning = self.factory.getRtiAmbassador()
        owner_callbacks = _JniCallbacks()
        resigning_callbacks = _JniCallbacks()
        owner_connected = resigning_connected = created = False
        owner_joined = resigning_joined = False

        def drain(rounds: int = 20) -> None:
            for _ in range(rounds):
                owner.evokeCallback(0.0)
                resigning.evokeCallback(0.0)

        try:
            owner.connect(owner_callbacks, CallbackModel.HLA_EVOKED)
            owner_connected = True
            resigning.connect(resigning_callbacks, CallbackModel.HLA_EVOKED)
            resigning_connected = True
            owner.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            owner.joinFederationExecution(
                "jni-save-resign-owner",
                federation_name,
                federateName="jni-save-resign-owner",
            )
            owner_joined = True
            resigning.joinFederationExecution(
                "jni-save-resigning-member",
                federation_name,
                federateName="jni-save-resigning-member",
            )
            resigning_joined = True

            owner.requestFederationSave("jni-resignation-save")
            resigning.resignFederationExecution(ResignAction.NO_ACTION)
            resigning_joined = False
            for _ in range(20):
                drain(1)
                if owner_callbacks.save_failures:
                    break
            self.assertEqual(
                owner_callbacks.save_failures,
                [SaveFailureReason.FEDERATE_RESIGNED_DURING_SAVE],
            )
            with self.assertRaises(SaveNotInitiated):
                owner.federateSaveBegun()

            # The failed operation must clear so the remaining member can use
            # the same C++ federation control plane for a later save.
            owner.requestFederationSave("jni-post-resignation-save")
            drain()
            owner.federateSaveBegun()
            owner.federateSaveComplete()
            drain()
            self.assertEqual(owner_callbacks.saved_count, 1)
            owner.resignFederationExecution(ResignAction.NO_ACTION)
            owner_joined = False
            owner.destroyFederationExecution(federation_name)
            created = False
        finally:
            if owner_connected:
                try:
                    if owner_joined:
                        owner.resignFederationExecution(ResignAction.NO_ACTION)
                    owner.disconnect()
                except Exception:
                    pass
            if resigning_connected:
                try:
                    if resigning_joined:
                        resigning.resignFederationExecution(ResignAction.NO_ACTION)
                    resigning.disconnect()
                except Exception:
                    pass
            if created:
                try:
                    owner.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            owner._implementation.close()
            resigning._implementation.close()

