            def assert_report(index: int, service_name: str, exception_name: str) -> None:
                for _ in range(20):
                    observer.evokeCallback(0.0)
                    if len(observer_callbacks.received_interactions) > index:
                        break
                self.assertEqual(len(observer_callbacks.received_interactions), index + 1)
