            self.assertEqual(fqr_callbacks.order, ["directed", "flush-grant"])
            self.assertEqual(tara_callbacks.order, ["directed", "grant"])
            self.assertEqual(nmra_callbacks.order, ["directed", "grant"])
            self.assertEqual(len(fqr_callbacks.flush_queue_grants), 1)
