    def test_cpp_jni_java_jpype_mixed_regional_timestamped_update_retracts_before_time_grants(
        self,
    ) -> None:
        """Retract one regional C++ TSO before its three Java grants complete."""
        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                super().flushQueueGrant(time, optimisticTime)
                self.order.append("flush-grant")

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-tso-retract-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        fqr = self.factory.getRtiAmbassador()
        tara = self.factory.getRtiAmbassador()
        nmra = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        fqr_callbacks = OrderedCallbacks()
        tara_callbacks = OrderedCallbacks()
        nmra_callbacks = OrderedCallbacks()
        receivers = (
            (fqr, fqr_callbacks, "jni-regional-tso-retract-fqr"),
            (tara, tara_callbacks, "jni-regional-tso-retract-tara"),
            (nmra, nmra_callbacks, "jni-regional-tso-retract-nmra"),
        )
        created = publisher_joined = False
        receiver_joined = {name: False for _, _, name in receivers}
        publisher_region: RegionHandle | None = None
        receiver_regions: list[tuple[RTIambassador, RegionHandle, AttributeSetRegionSetPairList]] = []
        publisher_pairs: AttributeSetRegionSetPairList | None = None
        object_instance: ObjectInstanceHandle | None = None

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                for ambassador, _, _ in receivers:
                    ambassador.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            region: RegionHandle,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([attribute]), RegionHandleSet([region])
                )
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            for ambassador, callbacks, _ in receivers:
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            publisher.joinFederationExecution(
                "jni-regional-tso-retract-publisher", federation_name
            )
            publisher_joined = True
            for ambassador, _, name in receivers:
                ambassador.joinFederationExecution(name, federation_name)
                receiver_joined[name] = True

            publisher_class = publisher.getObjectClassHandle(
                "HLAobjectRoot.Food.Drink.Soda"
            )
            publisher_attribute = publisher.getAttributeHandle(publisher_class, "Flavor")
            publisher_dimension = publisher.getDimensionHandle("SodaFlavor")
            publisher_attributes = AttributeHandleSet([publisher_attribute])
            publisher.publishObjectClassAttributes(publisher_class, publisher_attributes)
            publisher.changeDefaultAttributeOrderType(
                publisher_class, publisher_attributes, OrderType.TIMESTAMP
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher.setRangeBounds(publisher_region, publisher_dimension, RangeBounds(0, 2))
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            publisher_pairs = pair_list(publisher, publisher_attribute, publisher_region)

            for ambassador, _, _ in receivers:
                receiver_class = ambassador.getObjectClassHandle(
                    "HLAobjectRoot.Food.Drink.Soda"
                )
                receiver_attribute = ambassador.getAttributeHandle(receiver_class, "Flavor")
                receiver_dimension = ambassador.getDimensionHandle("SodaFlavor")
                receiver_region = ambassador.createRegion(
                    DimensionHandleSet([receiver_dimension])
                )
                ambassador.setRangeBounds(
                    receiver_region, receiver_dimension, RangeBounds(1, 3)
                )
                ambassador.commitRegionModifications(RegionHandleSet([receiver_region]))
                receiver_pairs = pair_list(ambassador, receiver_attribute, receiver_region)
                ambassador.subscribeObjectClassAttributesWithRegions(
                    receiver_class, receiver_pairs, active=True
                )
                self.assertFalse(ambassador.getConveyRegionDesignatorSetsSwitch())
                ambassador.setConveyRegionDesignatorSetsSwitch(True)
                ambassador.enableTimeConstrained()
                receiver_regions.append((ambassador, receiver_region, receiver_pairs))
            pump()

            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            pump()
            for _, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.discovered_objects), 1)
                self.assertEqual(callbacks.discovered_objects[0][0], object_instance)

            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = bytes((0x52, 0x45, 0x54, 0x2D, 0x46))
            values = AttributeHandleValueMap({publisher_attribute: b"RETRA"})
            retraction = publisher.updateAttributeValuesWithTime(
                object_instance,
                values,
                publisher.getTimeFactory().makeLogicalTime(8),
                tag,
            )
            self.assertTrue(retraction.isValid())
            for _, callbacks, _ in receivers:
                self.assertEqual(callbacks.timestamped_reflections, [])

            fqr.flushQueueRequest(fqr.getTimeFactory().makeLogicalTime(10))
            tara.timeAdvanceRequestAvailable(tara.getTimeFactory().makeLogicalTime(7))
            nmra.nextMessageRequestAvailable(nmra.getTimeFactory().makeLogicalTime(7))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            publisher.retract(retraction)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
            pump()

            self.assertEqual(len(publisher_callbacks.time_advance_grants), 1)
            self.assertEqual(publisher_callbacks.time_advance_grants[0].getTime(), 2)
            for callbacks in (fqr_callbacks, tara_callbacks, nmra_callbacks):
                self.assertEqual(callbacks.timestamped_reflections, [])
                self.assertEqual(callbacks.retraction_requests, [])
            self.assertEqual(fqr_callbacks.order, ["flush-grant"])
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][0].getTime(), 7)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][1].getTime(), 10)
            self.assertEqual(tara_callbacks.order, ["grant"])
            self.assertEqual(tara_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(nmra_callbacks.order, ["grant"])
            self.assertEqual(nmra_callbacks.time_advance_grants[0].getTime(), 7)
        finally:
            if object_instance is not None and publisher_pairs is not None:
                try:
                    publisher.unassociateRegionsForUpdates(object_instance, publisher_pairs)
                except Exception:
                    pass
            for ambassador, _, pairs in receiver_regions:
                try:
                    ambassador.unsubscribeObjectClassAttributesWithRegions(
                        ambassador.getObjectClassHandle("HLAobjectRoot.Food.Drink.Soda"),
                        pairs,
                    )
                except Exception:
                    pass
            for ambassador, region, _ in receiver_regions:
                try:
                    ambassador.deleteRegion(region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            for ambassador, _, name in reversed(receivers):
                if receiver_joined[name]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, _, _ in receivers:
                ambassador.disconnect()
            publisher.disconnect()
            for ambassador, _, _ in receivers:
                ambassador._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_regional_interaction_retraction_sequence(
        self,
    ) -> None:
        """Preserve regional TSO retraction and convey behavior across grants."""
        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def receiveInteraction(self, *arguments: object, **keywords: object) -> None:
                super().receiveInteraction(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("interaction")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-interaction-sequence-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = OrderedCallbacks()
        created = publisher_joined = receiver_joined = False
        publisher_region: RegionHandle | None = None
        receiver_region: RegionHandle | None = None
        interaction: InteractionClassHandle | None = None

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            publisher.joinFederationExecution(
                "publisher", federation_name, federateName="jni-regional-interaction-publisher"
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "subscriber", federation_name, federateName="jni-regional-interaction-receiver"
            )
            receiver_joined = True
            publisher_federate = publisher.getFederateHandle(
                "jni-regional-interaction-publisher"
            )

            interaction = publisher.getInteractionClassHandle(
                "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
            )
            parameter = publisher.getParameterHandle(interaction, "TemperatureOk")
            dimension = publisher.getDimensionHandle("ServerId")
            receiver_interaction = receiver.getInteractionClassHandle(
                "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
            )
            receiver_dimension = receiver.getDimensionHandle("ServerId")
            parameter_values = ParameterHandleValueMap({parameter: b"\x4D\x0A"})
            publisher.publishInteractionClass(interaction)
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)

            publisher_region = publisher.createRegion(DimensionHandleSet([dimension]))
            publisher.setRangeBounds(publisher_region, dimension, RangeBounds(0, 10))
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            receiver_region = receiver.createRegion(
                DimensionHandleSet([receiver_dimension])
            )
            receiver.setRangeBounds(receiver_region, receiver_dimension, RangeBounds(5, 15))
            receiver.commitRegionModifications(RegionHandleSet([receiver_region]))
            receiver.subscribeInteractionClassWithRegions(
                receiver_interaction, RegionHandleSet([receiver_region]), active=True
            )
            receiver.enableTimeConstrained()
            pump()
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()

            tag = bytes((0x6B, 0x22))
            with self.assertRaises(InvalidLogicalTime):
                publisher.sendInteractionWithRegionsWithTime(
                    interaction,
                    parameter_values,
                    RegionHandleSet([publisher_region]),
                    publisher.getTimeFactory().makeLogicalTime(4),
                    tag,
                )

            first = publisher.sendInteractionWithRegionsWithTime(
                interaction,
                parameter_values,
                RegionHandleSet([publisher_region]),
                publisher.getTimeFactory().makeLogicalTime(6),
                tag,
            )
            self.assertTrue(first.isValid())
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])
            receiver.timeAdvanceRequest(receiver.getTimeFactory().makeLogicalTime(6))
            publisher.retract(first)
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()
            self.assertEqual(len(receiver_callbacks.time_advance_grants), 1)
            self.assertEqual(receiver_callbacks.time_advance_grants[0].getTime(), 6)
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])
            self.assertEqual(receiver_callbacks.retraction_requests, [])
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(first)

            second = publisher.sendInteractionWithRegionsWithTime(
                interaction,
                parameter_values,
                RegionHandleSet([publisher_region]),
                publisher.getTimeFactory().makeLogicalTime(7),
                tag,
            )
            self.assertTrue(second.isValid())
            receiver.timeAdvanceRequest(receiver.getTimeFactory().makeLogicalTime(7))
            pump()
            self.assertEqual(len(receiver_callbacks.time_advance_grants), 2)
            self.assertEqual(receiver_callbacks.time_advance_grants[1].getTime(), 7)
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 1)
            report = receiver_callbacks.timestamped_interactions[0]
            self.assertEqual(report[0], receiver_interaction)
            self.assertEqual(dict(report[1]), {parameter: b"\x4D\x0A"})
            self.assertEqual(report[2], tag)
            self.assertEqual(report[4], publisher_federate)
            self.assertIsNone(report[5])
            self.assertEqual(report[6].getTime(), 7)
            self.assertEqual(report[7], OrderType.TIMESTAMP)
            self.assertEqual(report[8], OrderType.TIMESTAMP)
            self.assertEqual(report[9], second)
            self.assertEqual(receiver_callbacks.order, ["grant", "interaction", "grant"])
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(second)

            receiver.setConveyRegionDesignatorSetsSwitch(True)
            third = publisher.sendInteractionWithRegionsWithTime(
                interaction,
                parameter_values,
                RegionHandleSet([publisher_region]),
                publisher.getTimeFactory().makeLogicalTime(8),
                tag,
            )
            self.assertTrue(third.isValid())
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(3))
            receiver.timeAdvanceRequest(receiver.getTimeFactory().makeLogicalTime(8))
            pump()
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 2)
            conveyed = receiver_callbacks.timestamped_interactions[-1]
            self.assertEqual(conveyed[6].getTime(), 8)
            self.assertEqual(conveyed[5], RegionHandleSet([publisher_region]))
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(third)
        finally:
            if receiver_joined:
                try:
                    receiver.unsubscribeInteractionClassWithRegions(
                        receiver.getInteractionClassHandle(
                            "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
                        ),
                        RegionHandleSet([receiver_region]) if receiver_region else RegionHandleSet(),
                    )
                except Exception:
                    pass
            if receiver_region is not None:
                try:
                    receiver.deleteRegion(receiver_region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            receiver.disconnect()
            publisher.disconnect()
            receiver._implementation.close()
            publisher._implementation.close()

    def test_cpp_jni_java_jpype_timestamped_regional_interaction_survives_reenable(
        self,
    ) -> None:
        """Preserve one queued regional interaction across constrained re-enable."""
        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-interaction-reenable-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        receiver = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        receiver_callbacks = _JniCallbacks()
        publisher_connected = receiver_connected = False
        publisher_joined = receiver_joined = created = False
        publisher_region: RegionHandle | None = None
        receiver_region: RegionHandle | None = None

        def pump(rounds: int = 20) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                receiver.evokeCallback(0.0)

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            publisher_connected = True
            receiver.connect(receiver_callbacks, CallbackModel.HLA_EVOKED)
            receiver_connected = True
            publisher.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            publisher.joinFederationExecution(
                "publisher",
                federation_name,
                federateName="jni-regional-interaction-reenable-publisher",
            )
            publisher_joined = True
            receiver.joinFederationExecution(
                "subscriber",
                federation_name,
                federateName="jni-regional-interaction-reenable-receiver",
            )
            receiver_joined = True
            publisher_federate = publisher.getFederateHandle(
                "jni-regional-interaction-reenable-publisher"
            )

            interaction = publisher.getInteractionClassHandle(
                "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
            )
            receiver_interaction = receiver.getInteractionClassHandle(
                "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
            )
            parameter = publisher.getParameterHandle(interaction, "TemperatureOk")
            receiver_parameter = receiver.getParameterHandle(
                receiver_interaction, "TemperatureOk"
            )
            dimension = publisher.getDimensionHandle("ServerId")
            receiver_dimension = receiver.getDimensionHandle("ServerId")
            parameters = ParameterHandleValueMap({parameter: b"REG-REENABLE"})
            publisher.publishInteractionClass(interaction)
            publisher.changeInteractionOrderType(interaction, OrderType.TIMESTAMP)

            publisher_region = publisher.createRegion(DimensionHandleSet([dimension]))
            publisher.setRangeBounds(publisher_region, dimension, RangeBounds(8, 9))
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            receiver_region = receiver.createRegion(
                DimensionHandleSet([receiver_dimension])
            )
            receiver.setRangeBounds(receiver_region, receiver_dimension, RangeBounds(8, 9))
            receiver.commitRegionModifications(RegionHandleSet([receiver_region]))
            receiver.subscribeInteractionClassWithRegions(
                receiver_interaction,
                RegionHandleSet([receiver_region]),
                active=True,
            )
            receiver.setConveyRegionDesignatorSetsSwitch(True)
            receiver.enableTimeConstrained()
            pump()
            self.assertTrue(receiver_callbacks.time_constrained_enabled)
            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = b"regional-reenable-tag"
            retraction = publisher.sendInteractionWithRegionsWithTime(
                interaction,
                parameters,
                RegionHandleSet([publisher_region]),
                publisher.getTimeFactory().makeLogicalTime(6),
                tag,
            )
            self.assertTrue(retraction.isValid())
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])

            # The C++ queue owns the accepted passel. Re-enabling the standard
            # Java constrained role must not discard, duplicate, or rewrite it.
            receiver.disableTimeConstrained()
            pump()
            self.assertEqual(receiver_callbacks.timestamped_interactions, [])
            receiver.enableTimeConstrained()
            pump()
            self.assertEqual(len(receiver_callbacks.time_constrained_enabled), 2)

            receiver.timeAdvanceRequest(
                receiver.getTimeFactory().makeLogicalTime(6)
            )
            publisher.timeAdvanceRequest(
                publisher.getTimeFactory().makeLogicalTime(2)
            )
            pump()
            self.assertEqual(len(receiver_callbacks.timestamped_interactions), 1)
            self.assertEqual(len(receiver_callbacks.time_advance_grants), 1)
            report = receiver_callbacks.timestamped_interactions[0]
            self.assertEqual(report[0], receiver_interaction)
            self.assertEqual(
                report[1], ParameterHandleValueMap({receiver_parameter: b"REG-REENABLE"})
            )
            self.assertEqual(report[2], tag)
            self.assertEqual(report[4], publisher_federate)
            self.assertEqual(report[5], RegionHandleSet([publisher_region]))
            self.assertEqual(report[6].getTime(), 6)
            self.assertEqual(report[7], OrderType.TIMESTAMP)
            self.assertEqual(report[8], OrderType.TIMESTAMP)
            self.assertEqual(report[9], retraction)
            self.assertEqual(receiver_callbacks.time_advance_grants[0].getTime(), 6)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
        finally:
            if receiver_joined:
                try:
                    receiver.unsubscribeInteractionClassWithRegions(
                        receiver.getInteractionClassHandle(
                            "HLAinteractionRoot.CustomerTransactions.FoodServed.MainCourseServed"
                        ),
                        RegionHandleSet([receiver_region])
                        if receiver_region is not None
                        else RegionHandleSet(),
                    )
                except Exception:
                    pass
            if receiver_region is not None:
                try:
                    receiver.deleteRegion(receiver_region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            if receiver_joined:
                try:
                    receiver.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.CANCEL_THEN_DELETE_THEN_DIVEST)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            if receiver_connected:
                try:
                    receiver.disconnect()
                except Exception:
                    pass
            if publisher_connected:
                try:
                    publisher.disconnect()
                except Exception:
                    pass
            receiver._implementation.close()
            publisher._implementation.close()

