    def test_cpp_jni_java_jpype_timestamped_regional_object_update_available_advances(
        self,
    ) -> None:
        """Exercise all available-advance forms with a regional TSO update."""
        class OrderedCallbacks(_JniCallbacks):
            def __init__(self) -> None:
                super().__init__()
                self.order: list[str] = []

            def reflectAttributeValues(
                self, *arguments: object, **keywords: object
            ) -> None:
                super().reflectAttributeValues(*arguments, **keywords)
                if keywords.get("time") is not None or (
                    len(arguments) >= 7 and arguments[6] is not None
                ):
                    self.order.append("reflection")

            def timeAdvanceGrant(self, time: HLAinteger64Time) -> None:
                super().timeAdvanceGrant(time)
                self.order.append("grant")

            def flushQueueGrant(
                self, time: HLAinteger64Time, optimisticTime: HLAinteger64Time
            ) -> None:
                super().flushQueueGrant(time, optimisticTime)
                self.order.append("flush-grant")

        fom_module = (
            Path(__file__).parents[3]
            / "third_party"
            / "ieee1516.2-2025"
            / "resources"
            / "examples"
            / "RestaurantFOMmodule-2025.xml"
        )
        federation_name = f"python-jni-regional-object-available-{uuid4()}"
        publisher = self.factory.getRtiAmbassador()
        fqr = self.factory.getRtiAmbassador()
        tara = self.factory.getRtiAmbassador()
        nmra = self.factory.getRtiAmbassador()
        publisher_callbacks = _JniCallbacks()
        fqr_callbacks = OrderedCallbacks()
        tara_callbacks = OrderedCallbacks()
        nmra_callbacks = OrderedCallbacks()
        receivers = (
            (fqr, fqr_callbacks, "jni-regional-object-available-fqr"),
            (tara, tara_callbacks, "jni-regional-object-available-tara"),
            (nmra, nmra_callbacks, "jni-regional-object-available-nmra"),
        )
        created = publisher_joined = False
        receiver_joined = {name: False for _, _, name in receivers}
        publisher_region: RegionHandle | None = None
        publisher_pairs: AttributeSetRegionSetPairList | None = None
        receiver_regions: list[
            tuple[RTIambassador, RegionHandle, AttributeSetRegionSetPairList]
        ] = []
        object_instance: ObjectInstanceHandle | None = None

        def pump(rounds: int = 12) -> None:
            for _ in range(rounds):
                publisher.evokeCallback(0.0)
                for ambassador, _, _ in receivers:
                    ambassador.evokeCallback(0.0)

        def pair_list(
            ambassador: RTIambassador,
            attribute: AttributeHandle,
            region: RegionHandle,
        ) -> AttributeSetRegionSetPairList:
            pairs = ambassador.getAttributeSetRegionSetPairListFactory().create(1)
            pairs.add(
                AttributeSetRegionSetPair(
                    AttributeHandleSet([attribute]), RegionHandleSet([region])
                )
            )
            return pairs

        try:
            publisher.connect(publisher_callbacks, CallbackModel.HLA_EVOKED)
            for ambassador, callbacks, _ in receivers:
                ambassador.connect(callbacks, CallbackModel.HLA_EVOKED)
            publisher.createFederationExecution(
                federation_name, str(fom_module), "HLAinteger64Time"
            )
            created = True
            publisher.joinFederationExecution(
                "publisher",
                federation_name,
                federateName="jni-regional-object-available-publisher",
            )
            publisher_joined = True
            for ambassador, _, name in receivers:
                ambassador.joinFederationExecution(name, federation_name)
                receiver_joined[name] = True
            publisher_federate = publisher.getFederateHandle(
                "jni-regional-object-available-publisher"
            )

            publisher_class = publisher.getObjectClassHandle(
                "HLAobjectRoot.Food.Drink.Soda"
            )
            publisher_attribute = publisher.getAttributeHandle(publisher_class, "Flavor")
            publisher_dimension = publisher.getDimensionHandle("SodaFlavor")
            publisher_attributes = AttributeHandleSet([publisher_attribute])
            publisher.publishObjectClassAttributes(publisher_class, publisher_attributes)
            publisher.changeDefaultAttributeOrderType(
                publisher_class, publisher_attributes, OrderType.TIMESTAMP
            )
            publisher_region = publisher.createRegion(
                DimensionHandleSet([publisher_dimension])
            )
            publisher.setRangeBounds(
                publisher_region, publisher_dimension, RangeBounds(0, 2)
            )
            publisher.commitRegionModifications(RegionHandleSet([publisher_region]))
            publisher_pairs = pair_list(
                publisher, publisher_attribute, publisher_region
            )

            for ambassador, _, _ in receivers:
                receiver_class = ambassador.getObjectClassHandle(
                    "HLAobjectRoot.Food.Drink.Soda"
                )
                receiver_attribute = ambassador.getAttributeHandle(
                    receiver_class, "Flavor"
                )
                receiver_dimension = ambassador.getDimensionHandle("SodaFlavor")
                receiver_region = ambassador.createRegion(
                    DimensionHandleSet([receiver_dimension])
                )
                ambassador.setRangeBounds(
                    receiver_region, receiver_dimension, RangeBounds(1, 3)
                )
                ambassador.commitRegionModifications(RegionHandleSet([receiver_region]))
                receiver_pairs = pair_list(
                    ambassador, receiver_attribute, receiver_region
                )
                ambassador.subscribeObjectClassAttributesWithRegions(
                    receiver_class, receiver_pairs, active=True
                )
                self.assertFalse(ambassador.getConveyRegionDesignatorSetsSwitch())
                ambassador.setConveyRegionDesignatorSetsSwitch(True)
                ambassador.enableTimeConstrained()
                receiver_regions.append((ambassador, receiver_region, receiver_pairs))
            pump()

            object_instance = publisher.registerObjectInstanceWithRegions(
                publisher_class, publisher_pairs
            )
            pump()
            for _, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.discovered_objects), 1)
                self.assertEqual(callbacks.discovered_objects[0][0], object_instance)

            publisher.enableTimeRegulation(
                publisher.getTimeFactory().makeLogicalTimeInterval(5)
            )
            pump()
            self.assertTrue(publisher_callbacks.time_regulation_enabled)

            tag = b"jni-regional-object-available"
            retraction = publisher.updateAttributeValuesWithTime(
                object_instance,
                AttributeHandleValueMap({publisher_attribute: b"REG-AVA"}),
                publisher.getTimeFactory().makeLogicalTime(7),
                tag,
            )
            self.assertTrue(retraction.isValid())
            for _, callbacks, _ in receivers:
                self.assertEqual(callbacks.timestamped_reflections, [])

            fqr.flushQueueRequest(fqr.getTimeFactory().makeLogicalTime(10))
            tara.timeAdvanceRequestAvailable(tara.getTimeFactory().makeLogicalTime(7))
            nmra.nextMessageRequestAvailable(nmra.getTimeFactory().makeLogicalTime(10))
            publisher.timeAdvanceRequest(publisher.getTimeFactory().makeLogicalTime(2))
            pump()

            self.assertEqual(publisher_callbacks.time_advance_grants[0].getTime(), 2)
            for ambassador, callbacks, _ in receivers:
                self.assertEqual(len(callbacks.timestamped_reflections), 1)
                reflection = callbacks.timestamped_reflections[0]
                self.assertEqual(reflection[0], object_instance)
                self.assertEqual(list(dict(reflection[1]).values()), [b"REG-AVA"])
                self.assertEqual(reflection[2], tag)
                self.assertEqual(reflection[4], publisher_federate)
                self.assertEqual(reflection[5], RegionHandleSet([publisher_region]))
                self.assertEqual(reflection[6].getTime(), 7)
                self.assertEqual(reflection[7], OrderType.TIMESTAMP)
                self.assertEqual(reflection[8], OrderType.TIMESTAMP)
                self.assertEqual(reflection[9], retraction)
            self.assertEqual(fqr_callbacks.order, ["reflection", "flush-grant"])
            self.assertEqual(tara_callbacks.order, ["reflection", "grant"])
            self.assertEqual(nmra_callbacks.order, ["reflection", "grant"])
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][0].getTime(), 7)
            self.assertEqual(fqr_callbacks.flush_queue_grants[0][1].getTime(), 7)
            self.assertEqual(tara_callbacks.time_advance_grants[0].getTime(), 7)
            self.assertEqual(nmra_callbacks.time_advance_grants[0].getTime(), 7)
            with self.assertRaises(MessageCanNoLongerBeRetracted):
                publisher.retract(retraction)
        finally:
            if object_instance is not None and publisher_pairs is not None:
                try:
                    publisher.unassociateRegionsForUpdates(object_instance, publisher_pairs)
                except Exception:
                    pass
            for ambassador, _, pairs in receiver_regions:
                try:
                    ambassador.unsubscribeObjectClassAttributesWithRegions(
                        ambassador.getObjectClassHandle("HLAobjectRoot.Food.Drink.Soda"),
                        pairs,
                    )
                except Exception:
                    pass
            for ambassador, region, _ in receiver_regions:
                try:
                    ambassador.deleteRegion(region)
                except Exception:
                    pass
            if publisher_region is not None:
                try:
                    publisher.deleteRegion(publisher_region)
                except Exception:
                    pass
            for ambassador, _, name in reversed(receivers):
                if receiver_joined[name]:
                    try:
                        ambassador.resignFederationExecution(ResignAction.NO_ACTION)
                    except Exception:
                        pass
            if publisher_joined:
                try:
                    publisher.resignFederationExecution(ResignAction.NO_ACTION)
                except Exception:
                    pass
            if created:
                try:
                    publisher.destroyFederationExecution(federation_name)
                except Exception:
                    pass
            for ambassador, _, _ in receivers:
                ambassador.disconnect()
            publisher.disconnect()
            for ambassador, _, _ in receivers:
                ambassador._implementation.close()
            publisher._implementation.close()

