                subscriber_regional_dimension = subscriber.getDimensionHandle("SodaFlavor")
                regional_publisher_region = ambassador.createRegion(
                    DimensionHandleSet([regional_dimension])
                )
                regional_subscriber_region = subscriber.createRegion(
                    DimensionHandleSet([subscriber_regional_dimension])
                )
                ambassador.setRangeBounds(
                    regional_publisher_region, regional_dimension, RangeBounds(0, 2)
                )
